    cin >> n >> m >> k;

    long long x = 1, y = 1;

    if (k <= n - 1) {
        x += k;
    } else if (k <= n + m - 2) {
        x = n;
        y += k - (n - 1);
    } else {
        k -= n + m - 2;

        long long width = m - 1;
        long long rows = k / width;
        long long remaining = k % width;

        x = n - rows;
        y = (rows % 2 == 0 ? m : 2);

        if (remaining > 0) {
            --x;
            --remaining;

            if (rows % 2 == 0)
                y -= remaining;
            else
                y += remaining;
        }
    }

    cout << x << ' ' << y;
    return 0;
}

